class StateTracker {
    private:
        int running_sum = 0;
    public:
        StateTracker(int initial) : running_sum(initial) {}

        // Overload operator(): Object acts as a function
        int operator()(int value) {
            running_sum += value;
            return running_sum;
        }
    };

// Usage demonstrates internal state:
StateTracker summer(100);
int r1 = summer(10);    // 110
int r2 = summer(5);     // 115
